/* story-form-13 — cold yield; Volume evening CTA */
body.rp-cold-yielded .rp-stage-prop--shared-string,
body.rp-cold-yielded .rp-stage-prop--kite-high,
body.rp-cold-yielded .rp-stage-prop--chalk-cup { display: none !important; }
.rp-evening-volume-accept {
  margin: 0.75rem 0;
  padding: 0.75rem 0.9rem;
  background: rgba(14,10,8,.9);
  border: 1px solid rgba(232,180,120,.5);
  border-radius: 10px;
  color: #f2e6d8;
}
.rp-evening-volume-accept__h { font-weight: 700; margin: 0 0 0.35rem; }
.rp-evening-volume-accept__actions { display: flex; flex-wrap: wrap; gap: 0.45rem; margin-top: 0.55rem; }
.rp-evening-volume-accept__cta {
  padding: 0.4rem 0.7rem;
  border-radius: 8px;
  border: 1px solid #e8b478;
  background: #e8b478;
  color: #1a120c;
  font-weight: 700;
  font-size: 13px;
}
.rp-evening-volume-accept__cta--ghost {
  background: transparent;
  color: #e8b478;
}

integratorSnippet.pseudo:
function storyForm13() {
  return state.questPack?.storyForm13 || state.storyForm13 || null;
}

function isColdDay2Memory() {
  const day = state.save.dayIndex || 1;
  return day >= 2 && ["cold_open_mediate","cold_open_instigate","cold_open_stage"].some(storyFlag);
}

function coldShouldYield() {
  const f13 = storyForm13()?.coldDay2YieldPolicy;
  if (!f13) return false;
  if (!isColdDay2Memory()) return false;
  const day = state.save.dayIndex || 1;
  if (storyFlag("cold_day2_yielded") || storyFlag("natural_volume_street")) return true;
  if (day >= 7) return true;
  if (day >= 3 && [
    "arc_kite_antenna_complete","quest_antenna_complete","arc_kite_antenna_beat4",
    "flag_fence_and_kite","flag_kite_chaos_buff","natural_antenna_complete"
  ].some(storyFlag)) return true;
  return false;
}

function coldPropStillWins() {
  return isColdDay2Memory() && !coldShouldYield();
}

// DEPRECATED for winner gate — keep name but yield-aware:
function isColdDay2() {
  // Prefer coldPropStillWins for painting; memory stays for echoes
  return coldPropStillWins();
}

function applyColdYieldFlags() {
  if (!coldShouldYield()) return;
  const f = state.save.storyFlags;
  f.cold_day2_yielded = true;
  f.natural_volume_street = true;
  document.body.classList.add("rp-cold-yielded");
  const day = state.save.dayIndex || 1;
  if (day >= 10) {
    f.natural_ledger_street = true;
    f.natural_ledger_street_wins = true;
  }
}

function applyNaturalAntennaAdvance() {
  const rules = storyForm13()?.naturalAntennaAdvance?.rules || [];
  for (const r of rules) {
    if (!whenFlagsOk(r.when || {})) continue;
    for (const flag of r.setsFlags || []) state.save.storyFlags[flag] = true;
  }
}

function eveningVolumeAcceptHtml() {
  const cta = storyForm13()?.eveningVolumeAcceptCta;
  if (!cta || !whenFlagsOk(cta.when || {})) return "";
  return `<section class="rp-evening-volume-accept" data-testid="${cta.testId}">
    <p class="rp-evening-volume-accept__h">${loc(cta.headline)}</p>
    <p>${loc(cta.body)}</p>
    <div class="rp-evening-volume-accept__actions">
      <button class="rp-evening-volume-accept__cta" type="button" data-action="accept-volume-quest" data-testid="${cta.ctaAccept.testId}">${loc(cta.ctaAccept)}</button>
      <button class="rp-evening-volume-accept__cta rp-evening-volume-accept__cta--ghost" type="button" data-action="go-street" data-testid="${cta.ctaStreet.testId}">${loc(cta.ctaStreet)}</button>
    </div>
  </section>`;
}

